    const editor={scenes:{getActiveScene:()=>({tracks:{main:{elements:[{id:"clip",type:"video",mediaId:"media",startTime:3*120000,duration:61*120000}]}}})},media:{getAssets:()=>[{id:"media",url:"http://local/source",size:100,lastModified:1,bindingRevision:1}]}} as any;
