    interrupt=undefined;
    expect(ranges.map(r=>r.start)).toEqual([100,130]);
    const result=await collectTakeAudioEvidence({editor,elementIds:["clip"],signal:new AbortController().signal,boundedFrames:true,checkpoint:{key:"exact-source",store:new IndexedAudioCheckpoints({factory,databaseName:"resume"})}});
    expect(ranges.map(r=>r.start)).toEqual([100,130,130,160]);
    expect(result[0].frames[0].start).toBeCloseTo(1.01,4);
    expect(result[0].frames.at(-1)!.end).toBeCloseTo(62,4);
    const resumed=result[0].frames;
    ranges.length=0;
    const fresh=await collectTakeAudioEvidence({editor,elementIds:["clip"],signal:new AbortController().signal,boundedFrames:true});
    expect(resumed).toEqual(fresh[0].frames);
});
